with recent_products as (select * from products where array_contains(tags, 'eco') and array_contains(tags, 'sale')), brand_summary as (select brand, concat_ws(', ', sort_array(collect_set(category))) as category_values, sum(stock_qty) as total_stock_qty from recent_products group by brand) select brand, category_values, total_stock_qty from brand_summary order by total_stock_qty desc, brand desc;
